'use strict';
// The user guide shown on the Help page. The text is fixed (it contains no data from messages), so it is written as HTML.
const GUIDE = [
  { id: 'start', title: 'Getting started', html: `
    <p>NetEventPro receives syslog messages from your network devices, keeps them in a database on this computer, and shows them live in your browser. It also sends alerts, makes reports and keeps backups.</p>
    <ol><li><b>Install</b> with the setup program. It asks for the syslog port (default 514, UDP and TCP) and the dashboard port (default 8514), installs a Windows service and adds a firewall rule.</li>
    <li><b>Open the dashboard</b> at <code>http://localhost:8514/</code> (or the https address if you set up a certificate).</li>
    <li><b>Point your devices</b> at this computer's IP address, port 514. Each device appears on the <b>Devices</b> page after its first message.</li>
    <li><b>Check</b> <a href="#health">Health</a> shows green, then watch messages arrive on <a href="#logs">Logs</a>.</li></ol>
    <p>The left panel switches pages. Use <b>«</b> to collapse it to icons, <b>Full screen</b> for a wall display, and the theme button for light or dark.</p>` },
  { id: 'dashboard', title: 'Dashboard', html: `
    <p>The dashboard is a board of tiles. Everything on it follows the <b>time range</b> chosen at the top: a preset from 15 minutes to 30 days, today, yesterday, everything stored, or a custom from–to. <b>Refresh</b> reloads at once.</p>
    <h4>Several dashboards, sharing and the wall display</h4>
    <ul><li><b>New dashboard</b> (Customize) starts <b>empty</b>; add tiles with Add tile. <b>Reset layout</b> brings back the standard tiles.</li>
    <li><b>Export…</b> saves the dashboard as a file and <b>Import…</b> adds one from such a file (as a new named dashboard), to back one up or give it to a colleague.</li>
    <li><b>Wall display</b> (button on the Dashboard page): full screen without menus for a wall monitor; Esc leaves it. <b>Wall link</b> copies an address that opens a chosen dashboard directly in that mode (the wall computer signs in once).</li></ul>
    <h4>Arranging the board</h4>
    <ul><li>Click <b>Customize</b>. Drag a tile by its title bar to move it; drag its edge or corner to resize it. Other tiles make room. With a tile's title bar selected, arrow keys move it and Shift+arrows resize it.</li>
    <li><b>Add tile</b> opens the catalog. <b>Edit</b> on a tile changes its title, data and filter; <b>✕</b> removes it. <b>Reset layout</b> restores the standard board. Click <b>Done</b> when finished.</li></ul>
    <h4>Adding a tile: visual, data, look</h4>
    <ul><li><b>Customize → Add tile</b>: <b>step 1</b> pick a visual from the picture gallery (numbers, charts, rankings, lists, status). <b>Step 2</b> pick the <b>data</b> it shows. <b>Step 3</b> the editor opens with a live preview for colours and options.</li>
    <li><b>Data</b>: <b>Syslog messages</b>, <b>SNMP traps</b>, <b>Syslog + traps</b>, <b>Alarms</b> (open, acknowledged, escalated, cleared; by rule, device, severity, state), <b>Devices</b> (reporting, silent, muted, overdue, with open alarms; by vendor, status, group) and <b>System</b> (live counters). The tile header shows a small label with the data name, so you always know what a number counts. Turn it off in <b>Tile look → Show the data label</b>.</li>
    <li>You can change the <b>Visual</b> or the <b>Data</b> of an existing tile in the editor's <b>Data</b> group. Colours, looks and steps are kept. Clicking a bar, slice or row opens the matching page (messages, Alarms or Devices).</li>
    <li><b>Calculations</b> (Number and Gauge): percent of another number (for example alarms raised as a percent of messages), ratio, difference, sum, average per minute / hour / day, change or percent change since the period before, then multiply and add (for example × 60 to turn per second into per minute). Line graphs and messages over time can show a running total, a moving average, the rise per step or a per-minute rate.</li>
    <li><b>Device filter</b> (box at the top): type a device name to limit every tile of the dashboard to that device. Clear it for all devices. Devices-data tiles are not affected.</li>
    <li><b>Named dashboards</b>: the list at the top switches dashboards. In Customize mode use <b>Save as…</b> (copy of the current one), <b>New dashboard</b> (starts from the standard tiles), <b>Rename</b> and <b>Delete</b>. Each dashboard keeps its own tiles, look, time range and device filter. Up to 20.</li></ul>
    <h4>Designing tiles like Power BI or Grafana</h4>
    <p>Click <b>Customize</b>, then <b>Edit</b> on any tile. The editor shows a <b>live preview</b> on the left and the options in groups on the right. Every tile type has the same <b>Tile look</b> and <b>Title</b> options, including the <b>alarm cards</b>, which are now ordinary tiles.</p>
    <ul><li><b>Tile look</b>: one-click looks (Grafana panel, Power BI card, Glass, gradients, Neon glow), or your own: transparent, solid or gradient background with angle and opacity, border width and colour, accent edge, corner radius, shadow or glow, inner space, text colour.</li>
    <li><b>Title</b>: show or hide, align, size, colour, capital letters, and a solid or gradient <b>title bar</b>. Section headings have the same options (coloured band, text colour, size).</li>
    <li><b>Value</b> (numbers, gauges, alarm cards): size, alignment, decimals, short form (1.2k), unit before or after, a trend line behind the number, and the gauge style (half dial, full ring, segmented LCD bar, flat bar).</li>
    <li><b>Colour steps (thresholds)</b>: add steps such as 0 green, 50 amber, 100 red. The colour of the highest step reached colours the number, the dial, the bars, or fills the whole tile (solid or gradient). Ready-made sets are included.</li>
    <li><b>Chart</b> (line graphs and messages over time): line width, fill and gradient, smooth lines, points, stacked lines, bars, areas or lines, grid and axis numbers, legend below, at the right or hidden. <b>Chart colours</b> picks a palette (Power BI, Grafana, Warm, Cool, Neon, Pastel, Greys) for pies, bars, treemaps and tables.</li>
    <li>Width and height of the tile are also set in the editor.</li></ul>
    <h4>Whole-dashboard settings</h4>
    <ul><li>The <b>Syslog first / SNMP first</b> switch at the top chooses which section is shown first.</li>
    <li><b>Customize → Dashboard settings</b>: <b>Quick look</b> (Power BI, Grafana, Neon NOC, Executive or Plain) restyles every tile in one click; page background (solid or gradient), colour theme, default card style, corner radius, tile spacing, row height, accent colour and how often the numbers refresh.</li></ul>
    <h4>Tile types</h4>
    <table class="data"><tbody>
    <tr><td><b>Number</b></td><td>One big figure (messages, errors, devices, messages per minute, disk free …) with change against the previous period.</td></tr>
    <tr><td><b>Bar chart</b></td><td>Horizontal bars or vertical columns for the busiest devices, processes, severities, facilities or trap names. Click a bar to open those messages.</td></tr>
    <tr><td><b>Treemap</b></td><td>Rectangles sized by message count (Power BI style): the biggest sources stand out at once. Click a rectangle to open its messages.</td></tr>
    <tr><td><b>Table</b></td><td>A ranking table with count and share of the total.</td></tr>
    <tr><td><b>Bar gauge</b></td><td>Horizontal gauges that turn green, amber or red (Grafana style). Set <i>amber from</i> and <i>red from</i> per row, or leave empty for automatic.</td></tr>
    <tr><td><b>Number with trend line</b></td><td>A big figure with a small trend line behind it (Grafana “stat” panel); amber and red levels optional.</td></tr>
    <tr><td><b>Text note</b></td><td>Your own text for the shift: heading (<code>#</code>), bullets (<code>-</code>), <code>**bold**</code> and <code>[links](https://…)</code>.</td></tr>
    <tr><td><b>Gauge</b></td><td>The same figures on a dial. Set a maximum, a <i>warning from</i> level (amber) and a <i>critical from</i> level (red).</td></tr>
    <tr><td><b>Messages over time</b></td><td>Stacked bars by severity group. Hover a bar for the numbers.</td></tr>
    <tr><td><b>Line graph</b></td><td>The same data as lines, one per severity group or one for all messages, optionally filled.</td></tr>
    <tr><td><b>Pie / donut chart</b></td><td>Share of messages by severity, device, process or facility. Click a slice or legend row to open those messages on the Logs page.</td></tr>
    <tr><td><b>Heatmap</b></td><td>Either the busiest devices over time, or weekday against hour of day (in your browser's time zone). Darker = more messages.</td></tr>
    <tr><td><b>Severity breakdown</b>, <b>Top devices / processes</b></td><td>Ranked bars. Click a device to open its messages.</td></tr>
    <tr><td><b>Latest messages</b></td><td>The newest messages that match a filter. Click one for its details.</td></tr>
    <tr><td><b>Messages per second</b>, <b>Inputs and alert delivery</b>, <b>System health</b>, <b>Silent devices</b></td><td>Live status tiles.</td></tr></tbody></table>
    <p>Most tiles accept a <b>filter</b> (severities, device, process, text, tag), so you can build tiles such as “errors from the core switches” or “power failures this week”. The layout is saved on the server, so everyone sees the same board.</p>` },
  { id: 'logs', title: 'Logs', html: `
    <p>One page shows stored messages <i>and</i> new ones as they arrive. Pick a <b>time range</b> (15 minutes … 30 days, everything stored, or a custom range). New messages that match your filters appear at the top of the window straight away; with a custom range that ends in the past nothing new is added.</p>
    <p><b>One-day view</b> (the default): Logs, SNMP traps and Alarm history open on <b>today, 00:00 to 23:59</b>. The ◀ ▶ buttons or the date box show the previous and next days, “Today” jumps back. The other ranges (24 hours, 7 days, 30 days, custom) are still in the time-range list. Messages and traps are kept for 2 years by default (Settings → Storage).</p>
    <h4>Filtering</h4>
    <ul><li><b>Severity</b>: click the button and tick any combination (for example only Error and Warning). “Errors and worse” and “Warnings and worse” are shortcuts.</li>
    <li><b>Device</b> (name or IP; several separated by commas), <b>Process</b>, and <b>Search text</b>. In the text box: several words must all match; <code>-word</code> excludes; <code>"exact phrase"</code>; <code>tag:link-down</code> finds messages with that tag.</li>
    <li>Filters apply as you type. <b>Reset filters</b> clears them. <b>Pause</b> stops new rows from being added while you read.</li></ul>
    <h4>Reading and customising</h4>
    <ul><li>Click a row for the details panel (original packet, “Show only this device”, “Create rule from message”).</li>
    <li>Click a column heading to sort (again to reverse, a third time to reset); drag a heading's edge to resize (double-click to reset). <b>Columns</b> chooses, orders and wraps columns. <b>Appearance</b> sets font, size and colours per severity.</li>
    <li><b>Repeats</b> folds identical (or nearly identical) messages into one row with a ×N count.</li>
    <li><b>Views</b> saves the current range, filters, columns, sort and grouping under a name, to re-apply later.</li>
    <li><b>Export CSV / JSON</b> downloads everything that matches the current range and filters.</li></ul>` },
  { id: 'devices', title: 'Devices', html: `
    <p>A device is identified by the <b>name it writes in its own messages</b> (the host name in the syslog header). A device that sends no name is identified by the address the packets come from. So one device that sends from several addresses stays one device (the page shows “10.1.1.5 +1”), and two devices behind one NAT address stay separate if they name themselves.</p>
    <ul><li><b>Display name</b>: type a friendlier name; new messages use it.</li>
    <li><b>Columns</b>: drag a column edge to resize it; the Columns button chooses which are shown. Rows are compact, one line each.</li>
    <li><b>Silent</b>: a device that stops sending for the number of minutes set in Settings is flagged and an internal message is written; another message says when it is back. <b>Mute silence alert</b> turns this off for planned downtime.</li>
    <li><b>Logs</b> opens that device's last 24 hours. <b>Forget</b> removes it from the list (stored messages stay).</li></ul>` },
  { id: 'health', title: 'Health', html: `
    <p>NetEventPro watches itself: free disk space, database size and speed, listeners, receiving rate, delays inside the service, e-mail and forwarding. Each check is OK, Warning or Problem. When a check changes state and stays changed, NetEventPro writes a message from host <code>NetEventPro</code> — so rules and e-mail can react (use the rule template “NetEventPro health alerts (email)”). Disk warning and critical levels are in Settings.</p>` },
  { id: 'rules', title: 'Rules & alerts', html: `
    <p>A rule has <b>conditions</b> (all must match) and <b>actions</b>. Conditions: severities (tick any combination), device, process, tag, and message text (plain words, or a <code>/regular expression/i</code>). Actions: highlight colour, add a tag, play a sound, desktop notification, webhook (Slack, Teams, n8n … any URL), e-mail, or <b>discard</b> the message before it is stored. Rules run in order.</p>
    <ul><li><b>Cooldown</b> limits repeated webhook/e-mail alerts for one rule (default 60 s, 5 minutes for e-mail). Suppressed alerts are counted in the next one.</li>
    <li>Start from a <b>template</b> (interface down, failed logins, UPS on battery, mains failure …) and adjust.</li>
    <li><b>Vendor tags</b> (see Settings) make rules simple and robust: “Has tag <code>link-down</code>” instead of a regular expression.</li>
    <li><b>Export</b> saves all rules as a file; <b>Import</b> adds the rules of such a file to this list (to move them to another PC). Press Save rules afterwards.</li>
    <li><b>Flap detection</b> (Alarm section of a rule): when the same device and port changes several times within a few minutes you get <b>one “(flapping)” alarm</b> and one note when it settles, not an alarm per change. Works for syslog and SNMP trap rules.</li>
    <li>Notifications use <a href="#notify">profiles</a>: pick them from the dropdowns instead of typing addresses in every rule.</li>
    <li>Click <b>Save rules</b>; they are active immediately.</li></ul>` },
  { id: 'alarms', title: 'Alarms', html: `
    <p>The <b>Alarms</b> page is the list of problems that need somebody's attention, built from your rules. A rule with <b>Raise an alarm</b> turns a matching message into <b>one alarm per rule and device</b>: repeats only raise the counter, so a flapping port is one line, not hundreds.</p>
    <ul><li><b>Open</b> = nobody has looked at it. <b>Acknowledged</b> = someone owns it (their name and time are kept). <b>Cleared</b> = finished. Click an alarm for details, history and <b>notes</b> (ticket number, what was done).</li>
    <li><b>Auto-clear</b>: give the recovery rule “clear the alarms of …” and pick the alarm rule. A “link up” message then clears the “link down” alarm on that same device. The Rules page has ready-made pairs: link down/up, mains failure/restored, routing neighbour, communication lost/restored.</li>
    <li><b>Recovery e-mail</b>: when an alarm that was escalated by e-mail clears (you clear it, a “clear the alarms of …” rule clears it, or it clears itself), a green <b>CLEARED</b> e-mail goes to the same recipients, saying how long the alarm was open. Alarms that never escalated send nothing. Untick “e-mail when it clears” on the rule to turn it off. Nothing extra to install.</li>
    <li><b>Escalation</b>: set “escalate by e-mail after N min” on the rule. If nobody acknowledges the alarm in time, one e-mail goes to the rule's recipients (or the default list).</li>
    <li>The headings stay in view while you scroll, <b>Raised</b>, <b>Last repeat</b> and <b>Cleared</b> are single date-and-time columns.</li>
    <li>The red number in the menu is the count of open alarms; a new open alarm plays the alert sound when sound is on. Tick several alarms to acknowledge or clear them together. Cleared alarms are kept for 90 days.</li>
    <li>Everyone with “View” can see alarms; acknowledging, clearing and notes need the <b>Alarms</b> permission (built into the Operator role).</li></ul>` },
  { id: 'maintenance', title: 'Maintenance windows', html: `
    <p>Use a window for planned work or a nightly job so it does not cause alarms or e-mails. While a window is active for a device, its messages are <b>still stored and searchable</b> (tagged <code>maintenance</code>), but they raise no alarms, send no e-mail, webhook, sound or desktop alert, and the device cannot be reported <b>Silent</b>.</p>
    <ul><li><b>Devices</b>: names or addresses separated by commas; <code>*</code> works (<code>SW-DXB-*</code>). Empty = every device.</li>
    <li><b>One time</b> (from … to …) or <b>repeats weekly</b> on chosen days between two times of day; the end may be after midnight (22:00 to 02:00). Times are the server's local time.</li>
    <li>Recovery rules still clear existing alarms during a window. Alarms that were already open stay open until cleared.</li>
    <li>Needs the “rules” permission. Click <b>Save windows</b> to apply.</li></ul>` },
  { id: 'snmp', title: 'SNMP traps & MIBs', html: `
    <p><b>Where things are now:</b> SNMP receiver setup, MIB files and trap column views are in <b>Settings</b> (use the tabs at the top of Settings, which stay in view while you scroll). System health is the last section of the <b>Dashboard</b>; the Health item in the top bar shows its state. Syslog and SNMP traps are kept apart: <b>Logs</b> shows syslog only, <b>Traps</b> shows SNMP traps only, and <b>Rules &amp; alerts</b> has two tabs, <b>Syslog rules</b> and <b>SNMP trap rules</b>. A rule only ever runs on its own kind of message. Alarms from both appear on the single <b>Alarms</b> page, with a Source column and filter. The dashboard has an <b>SNMP traps</b> section with its own tiles (the Customize button edits them). The <b>SNMP &amp; MIBs</b> section receives SNMP traps (v1 and v2c, plus v2c informs) on <b>UDP port 162</b> and stores each one as a normal log message: application <code>snmptrap</code>, tag <code>snmp</code> and <code>trap:&lt;name&gt;</code>. Everything else works as for syslog (on the Traps page): search, colours, rules, alarms, e-mail, reports, forwarding.</p>
    <ul><li><b>Setup</b>: on each device set the trap destination to this computer, UDP 162, SNMP v2c (v1 if the device is old) with a community name. SNMPv3 is supported (see below).</li>
    <li><b>SNMPv3</b>: Settings → SNMP &amp; MIBs → <b>SNMPv3 users</b>. Create the same user on the device and here, with the same security level, authentication (SHA, MD5, SHA-2) and encryption (AES-128/192/256 or DES) and passwords of 8 or more characters. For <b>traps</b> nothing else is needed on this computer's side (the device uses its own engine ID). For <b>informs</b> the device must use this computer's engine ID, shown on the screen. If a v3 message is refused, the receiver status and a log message say why (unknown user, wrong password, wrong encryption password, wrong security level). The trap forwarder can also send SNMPv3: choose SNMPv3 for the manager and give the manager this computer's engine ID.</li>
    <li><b>MIB files</b>: a trap carries only numbers (OIDs). Upload the MIB files of your equipment (<b>Upload MIB files…</b>, several at once, any order) and traps are shown by name, e.g. <code>SOME-UPS-MIB::upsOnBattery (1.3.6.1.4.1.…): upsBatteryStatus.0 = low(3)</code>. Download MIBs from the vendor's support site. SMIv1 and SMIv2 text files are understood.</li>
    <li><b>MIBs still needed</b> lists numbers that could not be named, grouped by vendor, with a count: upload that vendor's MIB.</li>
    <li><b>Severity</b> is chosen from the trap: standard traps use fixed levels (linkDown = error); otherwise the words in the name decide (“Failure”, “Lost” = error; “High”, “Threshold” = warning; “Restored”, “Up”, “Normal” = notice). Add your own <b>Severity rules</b> (<code>upsOnBattery = critical</code>) for exceptions.</li>
    <li><b>Alarms</b>: standard linkDown/linkUp traps carry the tags <code>link-down</code>/<code>link-up</code>, so the “link down / link up” templates on the <b>SNMP trap rules</b> tab work. For other traps use a rule on that tab with “Trap” set to the trap name (or a number prefix such as <code>1.3.6.1.4.1.318</code>), and a second rule that clears the first.</li>
    <li><b>Trap columns</b> (Settings → Trap columns): one table for all vendors. Each column has a name, the value(s) to show (<code>{a|b}</code> takes the first that exists) and an optional <b>lookup</b>: lines like <code>5=Critical; 4=Minor; 3=Cleared</code>. Because numbers differ per vendor, start a line with <code>@ 1.3.6.1.4.1.674.10892:</code> (an OID prefix, a trap name or /regex/) to use that lookup only for those traps. Several values of one meaning go in <b>one entry</b>: <code>@ 1.3.6.1.4.1.12148: 0,2,3,8=Critical; 1=Cleared</code> (separate the values with a comma or <code>|</code>; a range of numbers is written <code>2-5=Critical</code>). Tick “This column is the severity” and the trap gets that severity everywhere (colours, alarms, reports, exports). Use <b>Export / Import</b> to copy views to another PC.</li>
    <li><b>Minor</b> (between Error and Warning) and <b>Cleared</b> (after Notice) are available wherever a severity is chosen.</li>
    <li><b>Text replacement for traps</b> (Settings → Text replacement): choose “SNMP trap name and values” and tick the <b>Trap columns</b> to change (none ticked = all columns of your trap column views). It is applied when traps are shown and exported, so <b>traps that are already stored change too</b>, and removing or editing a rule changes them back. “Only in trap value” limits a rule to one trap variable (for example <code>alertCurrentStatus</code>, 5 → Critical). The stored trap, the Severity colour and alarms are not affected; the Message column and the device name are changed as traps arrive.</li>
    <li>A device is identified by the address it sends from. To show a name instead, give the address a name on the Devices page.</li>
    <li>Look up any OID or name with the box on the page. The community name is never stored in the log. Without the “settings” permission you can see the page but not change it.</li></ul>` },
  { id: 'probes', title: 'Remote probes', html: `
    <p>Use a probe when some devices are in another network that cannot send syslog or traps directly to this server. A probe is a <b>small, lean NetEventPro</b> on a PC in that network: it receives syslog and SNMP traps, keeps them in a queue on disk and sends them to the main server. It has no database, rules, alarms, reports, MIB files, users or dashboard; all of that happens on the main server.</p>
    <ol><li>On the <b>main server</b>: Settings → Access &amp; updates: let the dashboard be opened from the network (and set a password, ideally HTTPS). Then Settings → <b>Remote probes</b> → type a name (for example the site) → <b>Add probe</b>. Copy the <b>token</b> (shown once).</li>
    <li>On the <b>probe PC</b>, run the setup program and choose <b>Probe only</b> (also when the PC already has NetEventPro: the page then offers “Keep as it is” for ordinary updates). Enter the main server address (for example <code>https://nms.example.com:8514</code>), the token and the name. For many sites use the silent form: <code>NetEventPro-Setup-&lt;version&gt;.exe /VERYSILENT /PROBE=1 /SERVER=https://nms.example.com:8514 /TOKEN=nep_xxx /NAME=SiteB</code></li>
    <li>Point the devices of that network at the probe PC (syslog UDP/TCP 514, traps UDP 162), exactly as you would for the main server.</li></ol>
    <p>An existing full installation can also be turned into a probe: Settings → Remote probes → “This computer is” → A probe. The service restarts as a probe. To go back, use <b>Switch back to a full NetEventPro</b> on the probe page.</p>
    <h4>The probe page</h4>
    <p>Open the dashboard shortcut on the probe PC (<code>http://127.0.0.1:8514/</code>). If Chrome will not open <code>localhost</code> but opens <code>127.0.0.1</code>, Chrome has remembered localhost as https-only from an earlier https dashboard: in Chrome open <code>chrome://net-internals/#hsts</code>, type <code>localhost</code> under “Delete domain security policies” and press Delete. It shows connected or not, the packets received, sent and waiting, and lets you change the server, token, name, ports, allowed sources and the update address. It opens <b>from the probe PC only</b>; nobody can open it over the network.</p>
    <ul><li>If the link is down the probe keeps up to 300,000 packets on disk and sends them when it is back (with their real receive time), also after a restart of the PC.</li>
    <li>Messages from a probe carry the tag <code>probe:&lt;name&gt;</code>; search with <code>tag:probe:Site-B</code>. “Accept syslog only from” on the main server applies to the real device addresses.</li>
    <li>The main server needs only one open port from the probe: its dashboard port. Use HTTPS when the link crosses an untrusted network; for a self-signed certificate tick the box on the probe page.</li>
    <li>SNMP informs are answered by the probe itself, so devices do not wait for the far server. SNMPv3 traps are decrypted on the main server (create the SNMPv3 users there).</li>
    <li><b>Updates</b>: enter the same release address and public key on the probe page (<a href="#updates">Updates</a>), Check, Install. A probe can be switched off or removed on the main server at any time.</li></ul>
    <h4>Probe security</h4>
    <ul><li><b>Password</b>: on the probe page, Security → Password for this page (10+ characters). After that the page needs a sign-in (30 minutes idle; five wrong tries lock that address for 10 minutes).</li>
    <li><b>Open from</b>: by default the page is only for the probe PC. “Other computers on the network” needs a password and can be limited to an allowed-addresses list; restart the service to apply. <b>Create a certificate</b> turns on HTTPS for the page (self-signed: the browser warns once).</li>
    <li><b>Pinned certificate</b>: “Pin the server's certificate…” shows the main server's certificate; accept it only when the SHA-256 matches the one on the server. From then on the probe sends nothing, not even the token, to a server with a different certificate. After the server's certificate is renewed, pin again. <b>Refuse plain http://</b> blocks an http address.</li>
    <li><b>Encrypted queue and token</b> on the probe's disk (key in <code>secret.key</code>). <b>Receive limit</b>: packets per second from one device (0 = off) so one noisy device cannot fill the queue. The page keeps an audit log.</li>
    <li>On the main server, Settings → Remote probes: <b>New token</b> (the old token keeps working for 24 hours so you can update the probe PC without a gap) and <b>Addresses</b> (the token is only accepted from those addresses).</li></ul>` },
  { id: 'notify', title: 'Notifications: profiles, e-mail, SMS, Teams', html: `
    <p>Settings → <b>Notifications</b>. A <b>profile</b> says <i>how</i> and <i>to whom</i> someone is told: e-mail addresses (To and Cc), a webhook (generic, Slack or <b>Microsoft Teams card</b>) and SMS numbers. A rule then only picks one or more profiles from a dropdown (“Notify” for the first message, “Alarm escalation” when nobody acknowledges in time), so the same people are set up once and not in every rule.</p>
    <ul><li><b>E-mail server</b>: host, port, security (none / STARTTLS / TLS), user and password, From. Use <b>Send test e-mail</b>.</li>
    <li><b>SMS gateway (SMPP 3.4)</b>: host, port, system id, password, bind type, sender. Works with any SMPP provider or SMSC. A bind error such as <code>0x0000000d</code> means the provider refused the login (check system id, password and that your IP address is allowed). Long messages are cut at 160 characters (70 with non-Latin text); multi-part SMS is not built yet.</li>
    <li><b>Webhook / Teams</b>: paste the address of the incoming webhook. The address contains a secret and is stored encrypted.</li>
    <li><b>Delivery log</b> lists every notification sent or failed, with the reason. Check it first when a message did not arrive.</li>
    <li>Rules from older versions were converted to profiles automatically; the old e-mail and webhook fields no longer exist in the rule window.</li></ul>` },
  { id: 'sqlcopy', title: 'SQL Server copy', html: `
    <p>Settings → <b>SQL Server</b> keeps a copy of the logs, SNMP traps, alarms and devices in a Microsoft SQL Server database, for Power BI, reports or other tools. The local database stays the main store; the copy catches up by itself after an outage and never duplicates rows (it remembers where it stopped).</p>
    <ol><li>Enter the server (for example <code>SQLHOST\SQLEXPRESS</code>), the database name and the login: <b>Windows</b> uses the account the NetEventPro service runs as (by default <code>NT AUTHORITY\SYSTEM</code>); <b>SQL login</b> uses the user and password you type.</li>
    <li>The login needs permission to create tables, or to create the database when “Create the database if it is missing” is ticked (<code>CREATE DATABASE permission denied</code> means it has not). Easiest: create an empty database yourself and give the login <code>db_owner</code> on it.</li>
    <li><b>Test</b>, then switch the copy on. The page shows the state, rows copied and the last error.</li></ol>
    <p>Tables: <code>ne_logs</code>, <code>ne_alarms</code>, <code>ne_devices</code>. Views: <code>ne_syslog</code> (syslog messages) and <code>ne_traps</code> (SNMP traps), which are the easiest to query, for example <code>SELECT TOP 100 * FROM ne_syslog ORDER BY ts DESC</code>. Rows deleted locally by retention are not deleted in SQL Server. The password is stored encrypted.</p>` },
  { id: 'security', title: 'Security: sign-in, two-factor, audit log', html: `
    <p>Settings → Access &amp; updates → <b>Security</b>. Everything here is optional and mild by default, so nothing changes until you turn it on.</p>
    <ul><li><b>Two-factor sign-in</b> (My two-factor sign-in → Set up): in an authenticator app (Microsoft Authenticator, Google Authenticator, Authy …) add an account by typing the setup key, then type the 6-digit code to turn it on. <b>Save the 10 recovery codes</b>: each works once if the phone is lost. Signing in then asks for a code. An administrator can reset another account (Accounts table → Reset two-factor). Scripts that use Basic authentication cannot use a two-factor account; give scripts their own account.</li>
    <li><b>Password policy</b>: minimum length (8 to 20), optional complexity (three of lower case, upper case, digits, symbols; no user name inside), very common passwords refused. Applies to new passwords.</li>
    <li><b>Account lockout</b>: after N wrong passwords or codes the account is locked for N minutes (default 5 and 15). Unlock it in the Accounts table. The server's own console is never locked out. The address lock (5 tries, 5 minutes) still applies as well.</li>
    <li><b>Allowed addresses</b>: only these IP addresses or ranges may open the dashboard (empty = all). This computer is always allowed, and a list that would lock you out is refused. Probes are not affected.</li>
    <li><b>HSTS</b> (only when the dashboard runs on HTTPS) and a reminder switch for people without two-factor.</li>
    <li><b>Audit log</b>: sign-ins, failed sign-ins and codes, password changes, user and probe changes, security changes. Filter by text and <b>Download CSV</b>.</li>
    <li><b>Stored secrets</b>: passwords and tokens in the settings (SMTP, SMS, SQL Server, webhooks, report folders, SNMPv3, backup) and the two-factor secrets are <b>encrypted on disk</b> with <code>secret.key</code> in the data folder. <b>Keep secret.key with the data folder</b>: if only <code>config.json</code> is copied to another PC the encrypted passwords come up empty. Backups contain readable settings so they restore anywhere: use a backup passphrase for copies that leave the server.</li></ul>` },
  { id: 'polling', title: 'SNMP polling', html: `
    <p>NetEventPro can <b>ask</b> your devices how they are doing, not only listen to what they send. Open <b>SNMP polling</b> in the left menu.</p>
    <ol><li><b>Add device</b>: name, address, SNMP version and community (or SNMPv3 user and passwords). Press <b>Test connection</b>: it shows the device name, uptime and the number of interfaces. This is step 1.</li>
    <li><b>Step 2: readings.</b> On the device page, <b>Readings → Add a reading</b>. Each reading has its own name, unit, OID (<b>Pick from MIB</b> and <b>Test read</b> help), calculation (<i>raw × scale + offset</i>: a sensor that sends 4 for 20 °C and 5 for 25 °C needs scale 5), value meanings (words for status codes, or levels such as above 22 = Warning, above 25 = Critical), alarms and display (graph, card, bar). <b>Copy from another device</b> or <b>Use a template</b> (built-in sets such as Cisco and APC are included) saves typing; <b>Save as template</b> keeps a set for later.</li>
    <li>Every minute (you choose) the device is asked for its uptime and for the readings you added (and, if you chose them, its interfaces). Devices that have no readings yet use the built-in set that fits (<b>Generic</b>, <b>Cisco switch/router</b>, <b>APC UPS</b>); <i>Start from the built-in set</i> copies it into readings you can change.</li>
    <li>The device page shows graphs (6 hours to a year) and the interface table. On the first answer the interfaces that are <b>up</b> are watched (not loopbacks or VLANs); tick the others you want.</li>
    <li><b>Alarms</b>: add them to a reading (“above 30, clears at 25, for 5 minutes”), or use Settings → <b>Alarm limits</b> for limits that apply to many devices. They raise normal alarms (Alarms page, e-mail, SMS and the profiles you pick) and clear by themselves. Interface thresholds (status, traffic, errors) work per interface.</li>
    <li><b>No SNMP answer</b>: when a device misses the set number of polls in a row, an alarm is raised (optionally saying whether it still answers ping) and clears when it answers again.</li></ol>
    <p><b>Good to know</b>: polling runs from this computer, so it must reach the device on UDP port 161. For devices in another network choose <b>Poll from → Probe</b> on the device: the probe (see Remote probes) fetches its device list from this server, polls locally and sends the readings back over its HTTPS link, queueing them if the link is down. Alarms and thresholds are still evaluated here. If a probe stops reporting, its devices show “Probe not reporting” and no alarm is raised for them meanwhile. Passwords are stored encrypted. The first reading of an interface shows no traffic yet (rates need two polls). Readings are kept in full for 7 days, then as 5-minute averages for a year (Settings tab).</p>
    <p><b>Gentle on your devices</b>: a device is asked one question at a time with a short pause after each answer (Settings → <b>Pause between requests</b>, default 30 ms); tables are read 10 rows at a time and only the interfaces you watch are polled every round; polls of different devices are spread out and at most <b>5 devices</b> are asked at the same time; a device that stops answering is asked less and less often (up to every 10 minutes) until it answers again. For old or slow equipment raise the interval (60 s or more) and the pause. <b>MIB picker</b>: in a profile choose <b>Pick from MIB</b>, then a MIB file from the list or type words (name, module, file name or OID).</p>
    <p><b>Data types</b> (profile column): <i>Number</i>, <i>Counter</i> (per second), <i>Uptime ticks</i> (to seconds) and <i>Text</i>. Numbers that a device sends as text (\"12.4 V\") are read as numbers. <b>Lookups</b> (tab Lookups): a number becomes a word and a state (1 = up, 2 = down); Warning and Critical states raise an alarm by themselves, per table row. <b>Thresholds</b> can be above, below, at least, at most, equals, is not, and for text: changes, is, contains. Full guide for people coming from PRTG: <i>docs/PRTG-to-NetEventPro.md</i> in the program folder.</p>
    <p>SNMP polling is available to the <b>Administrator</b> only (permission “SNMP polling” in Users → Roles).</p>
    <p><b>More</b>: <b>Discover devices</b> scans addresses (for example 10.1.2.0/24) with your community or SNMPv3 user and adds the ones that answer. <b>Reports</b> shows availability and CPU, memory and temperature per device with CSV download. In <b>Profiles</b>, <b>Pick from MIB</b> builds your own profile from the MIB files you loaded (needed for Eltek, Spectracom, Eventide, DNWP and other vendors that have no built-in profile). The 5-minute averages can be copied to SQL Server (table <code>ne_poll</code>).</p>` },
  { id: 'scaling', title: 'Capacity and growing the system', html: `
    <p>What this server handles, and what to do when the network grows. The numbers come from tests on a small 2-core machine; <b>test on your own server</b> (see below).</p>
    <h3>What was measured</h3>
    <ul><li><b>Syslog:</b> 5,000 messages per second and 20,000 per second were received and stored without loss on a 2-core test machine. At 50,000/s some packets were lost in the operating system's UDP buffer. For planning, treat <b>10,000 per second</b> as the upper limit of one server and stay well below it.</li>
    <li><b>Polling:</b> 200 devices with 20 single-value readings each, every 60 s, were all answered within 20 seconds (fake devices on the same machine, so the network was not part of it). Readings are asked in batches, so 20 readings need about 3 packets per device per poll.</li>
    <li><b>Disk:</b> about 380 bytes per stored syslog message and about 80 bytes per stored reading, indexes included.</li></ul>
    <h3>Rules of thumb</h3>
    <ul><li>One computer: up to a few hundred devices at 60 s, up to a few thousand syslog messages per second. Check <b>System health</b>: "Polling keeps up", "Processing delay", "Database writer" and "UDP receive buffer" should stay OK.</li>
    <li>Use <b>SNMP polling → Settings → Capacity estimator</b> with your numbers before adding many devices.</li>
    <li><b>At the same time</b> is raised automatically when polls fall behind (up to 50). A device is never asked more than one thing at a time.</li></ul>
    <h3>When it grows</h3>
    <ol><li><b>Polling falls behind</b> ("Polling keeps up" warns): use a longer interval for slow-changing readings, fewer readings, or put a <b>remote probe</b> at the site so the probe polls its own devices and only sends results. Settings → SNMP polling → <i>Where polling runs</i> shows how many devices each probe and this computer poll.</li>
    <li><b>Syslog bursts are lost</b> (receive buffer warning, or Received lower than what devices send): raise the <b>UDP receive buffer</b> in Settings → Network (64 MB or more), use a faster disk, and cut noisy sources.</li>
    <li><b>The database writer falls behind</b> ("Database writer" shows a high queue peak): faster disk (SSD or NVMe), fewer days in the database, less noise.</li>
    <li><b>Beyond one server:</b> run a second NetEventPro for another region or another set of devices, each with its own probes, and use the SQL Server copy to bring the data together. One instance does not share work with another.</li></ol>
    <h3>Test tools (in the tools folder)</h3>
    <ul><li><code>node tools/loadtest.js --host SERVER --port 514 --rate 500 --seconds 60</code> sends test syslog at a steady rate. Compare what it sent with <b>Received</b> on System health.</li>
    <li><code>node tools/fake-device.js --addresses 200</code> answers as 200 SNMP devices on 127.0.1.1 upwards, to try polling at size on one computer.</li></ul>
  ` },
  { id: 'whatsnew', title: 'What\'s new', html: `
    <ul><li><b>1.62.0</b> Alarms page: <b>Delete all N</b> removes every alarm that matches the current filters, not only the 300 shown (confirmation shows the count; needs the Delete permission).</li><li><b>1.61.0</b> A flood of messages (more than about 60 per second) no longer freezes the browser: the page redraws twice a second, shows a "Very busy" note with a Pause link, and nothing is lost. No delay at normal rates.</li><li><b>1.60.0</b>: 'Polling keeps up' health check, fair scheduling and automatic workers, write-queue peak, 'Where polling runs' per probe, capacity guide.</li><li><b>1.59.0</b>: fewer SNMP packets per device (readings batched), read-only community reminder, UDP receive buffer setting, 'service was suspended' notice, Capacity estimator and load-test tools.</li><li><b>1.58.1</b>: polled-tile dialog keeps its buttons in view; honeycomb hexagons in the heatmap.</li><li><b>1.58.0</b>: dashboard tile for SNMP polling (device status by group, polling alarms, any readings of any devices in a table, tile grid, bars, gauge or graph); tile shapes incl. hexagon; heatmap shapes and colour themes.</li><li><b>1.57.0</b>: Edit layout on a device page (drag to reorder, corner handle to resize tiles and graphs, saved per device); groups of polled devices with group chips and counts.</li><li><b>1.56.0</b>: removed readings leave no values; ✎ on every visual; ⚙ options for every graph (also Answer time); resizable table columns; switch to keep polling alarms out of the syslog list.</li><li><b>1.55.0</b>: polling alarms no longer trigger your general syslog rules (no double notification); click the alarm badge of a reading to see its rules and open alarms; show readings as gauge, bar, big number, status light or tile grid; compact readings table.</li><li><b>1.54.1</b>: Pick from MIB in the reading editor: MIB file drop-down, search and paging.</li><li><b>1.54.0</b>: value meanings are rules (above / below / between, first fit wins, keep until) so levels such as “above 22 Warning, above 25 Critical” work for every reading; Warning and Critical tell different people.</li><li><b>1.53.0</b>: SNMP polling by device: step 1 add the device, step 2 add its readings (name, unit, OID, calculation, value meanings, alarms, display), copy readings from another device, templates. Tabs: Devices, Reports, Settings.</li><li><b>1.52.6</b>: table metrics show a row summary (no average); fake SNMP device tool (<code>tools/fake-device.js</code>, see docs/FAKE-DEVICE.md).</li><li><b>1.52.5</b>: uptime is always shown; lookup metrics keep their graph; lookups/thresholds explained, with a clear Notify choice (tick-boxes, none = alarm only).</li><li><b>1.52.4</b>: table metrics draw a graph with one line per row; new devices poll only uptime and what you add (interfaces are an option).</li><li><b>1.52.3</b>: update-path test release (no program changes).</li><li><b>1.52.2</b>: fixes “signature is not valid” after the update boxes were removed (old saved address/key are ignored).</li><li><b>1.52.1</b>: Updates shows the release date of the newest version.</li><li><b>1.52.0</b>: <b>one-button updates</b> (no address or key to enter; works on any computer), a <b>compact Settings page</b> with one <b>Save changes</b> button and an unsaved-changes indicator.</li><li><b>1.51.0</b>: SNMP polling <b>data types</b> (number, counter, uptime ticks, text), <b>Lookups</b> (value → word and state, with automatic alarms), more threshold operators (equals, is not, text changes/contains), a Status panel on the device page, and a guide for moving from PRTG (docs/PRTG-to-NetEventPro.md).</li>
      <li><b>1.50.1</b>: <b>Pick from MIB</b> now offers every column of a table (named value lists and numbers sent as text are included) and names the rows by the table's comment column.</li>
      <li><b>1.50.0</b>: <b>Probes update from a server that was updated by the installer</b> (no internet needed). The <b>wall display clock</b> shows on every dashboard. <b>SNMP polling tables</b> can be read row by row (one value, graph and threshold per row; <b>Whole table</b> in Pick from MIB). Fixed: the <b>Latest messages</b> tile kept showing only errors after all severities were ticked.</li>
      <li><b>1.49.0</b>: <b>Signing in on a second PC no longer signs the first one out.</b> <b>Roles</b> are enforced everywhere: a Viewer sees dashboards, logs, traps, alarms, devices and health only (no Rules &amp; alerts, no settings); an Operator gets what the Operator role allows (Users → Roles). <b>SNMP polling is for the Administrator</b> (new permission “SNMP polling”). <b>Probes update with the main server</b> (Settings → Updates: signed package, checked by the probe, restart automatically). The <b>wall display</b> has a title bar with the date and the time. The <b>MIB picker</b> in polling profiles searches by MIB file, name, module or OID, has a MIB file list and pages instead of stopping at 100. <b>Polling is gentler on devices</b>: one question at a time per device with a pause, smaller table requests, and slower asking of devices that do not answer (Polling → Settings → Pause between requests).</li>
      <li><b>1.48.0</b>: <b>SNMP polling through a probe</b>: choose “Poll from” on a device (and in Discover devices) to poll it from a probe in another network. Test connection and discovery also run on the probe. Readings queue on the probe if the link is down.</li>
      <li><b>1.47.0</b>: <b>SNMP polling, step 2</b>: <b>Discover devices</b> (scan a range and add many at once), <b>Reports</b> tab (availability, CPU, memory, temperature, CSV), <b>Pick from MIB</b> in custom profiles, vendor name shown in Test connection, and the 5-minute averages can be copied to SQL Server (<code>ne_poll</code>).</li>
      <li><b>1.46.0</b>: <b>SNMP polling</b> (new page in the left menu): add devices (SNMP v1, v2c or v3) with Test connection, read CPU, memory, temperature, uptime and interface traffic and errors, see graphs, set thresholds that raise normal alarms, and get a “No SNMP answer” alarm when a device stops answering. Built-in profiles for generic devices, Cisco and APC UPS. See Help → SNMP polling.</li>
      <li><b>1.45.1</b>: <b>Help topics</b> for the notification profiles, SQL Server copy, Security and probe security were added (they only had “What's new” lines before).</li>
    <li><b>1.45</b>: <b>Passwords and tokens are encrypted on disk</b>: SMTP, SMS, SQL Server, webhook/Teams addresses, report-folder and SNMPv3 passwords, and the two-factor secrets. Nothing changes on screen. Keep <code>secret.key</code> together with the data folder; backups still restore on another computer.</li>
    <li><b>1.44</b>: <b>Probe security</b>. The probe page now has its own <b>password</b>, optional <b>HTTPS</b> and network access with an allowed-addresses list, an <b>encrypted queue and token</b>, <b>certificate pinning</b> for the link to the main server, a per-device receive limit and an audit log. On the main server (Remote probes) each probe has <b>New token</b> (old one works 24 h more) and <b>Addresses</b>.</li>
    <li><b>1.43</b>: <b>Security</b> (Settings → Access &amp; updates → Security): <b>two-factor sign-in</b> with an authenticator app and recovery codes, an <b>audit log</b> you can filter and download, a <b>password policy</b>, <b>account lockout</b>, an <b>allowed-addresses list</b> for the dashboard, HSTS, and stronger password hashing. Everything is optional and off or mild by default, so nothing changes until you turn it on. The probe gets its own security in 1.44.</li>
    <li><b>1.42.1</b>: <b>New dashboard now starts empty</b>: click Customize → Add tile to build it. “Reset layout” still brings back the standard tiles.</li>
    <li><b>1.42</b>: <b>Dashboard sharing</b>. In Customize: <b>Export…</b> downloads the dashboard as a file, <b>Import…</b> adds a dashboard from such a file (as a new named dashboard), so you can back one up or give it to a colleague. <b>Wall display</b> shows the dashboard full screen without menus (Esc or the small button at the bottom right leaves it); <b>Wall link</b> copies a link that opens a chosen dashboard straight in wall mode. The wall computer must sign in once: use a user with only the view permission, and set Settings → Access → idle time-out to “never” so it stays signed in.</li>
    <li><b>1.41</b>: <b>One-day view</b>: Logs, SNMP traps and Alarm history now open on <b>today, 00:00 to 23:59</b>. The ◀ ▶ buttons (or the date box) show the previous and next days, “Today” jumps back. “Last 24 hours”, 7 days, 30 days and Custom are still in the list. <b>Keep for 2 years</b>: messages and traps are now kept for 2 years by default, with no size limit; earlier settings shorter than 2 years were raised once to 2 years (change it in Settings → Storage &amp; time).</li>
    <li><b>1.40</b>: <b>Flap detection</b> for syslog and SNMP trap rules that raise alarms (Rules → Alarm → “flapping”). When the same device and port changes (down or up) several times within a few minutes, you get <b>one “(flapping)” alarm and one alert</b>; the single alarms and alerts stop until it has been quiet for the time you set, then the flapping alarm clears itself. Empty = off.</li>
    <li><b>1.39</b>: <b>SQL Server views</b>: <code>ne_traps</code> (only SNMP traps) and <code>ne_syslog</code> (only syslog messages) are created next to <code>ne_logs</code>, so reports and Power BI can use them like tables. Existing databases get them automatically a few seconds after the update.</li>
    <li><b>1.38.2</b>: <b>Rules &amp; alerts, Notifications, SQL Server and Reports are now tabs inside the Settings page</b> (old links and bookmarks open the right tab). The rule window is arranged in four labelled sections: Which messages, What happens to the message, Who is told, Alarm. Rules, reports and notification settings keep their own Save buttons.</li>
    <li><b>1.38.1</b>: <b>Rules &amp; alerts, Notifications, SQL Server and Reports now sit under Settings</b> in the side panel, and every icon has its own colour taken from the colour theme. In a rule, the profiles to tell are now chosen from a <b>compact drop-down</b> (when the rule matches, and separately when an alarm is escalated).</li>
    <li><b>1.38</b>: <b>Copy to SQL Server</b> (new <b>SQL Server</b> page). Keep a copy of syslog messages, SNMP traps, alarms (with every change) and devices in a Microsoft SQL Server database, using a Windows login or an SQL login, with an option to create the database and its tables. The local database stays as it is; if the SQL Server is down the copy waits and catches up by itself. Includes <b>Test connection</b>, a live status and “copy everything again”.</li>
    <li><b>1.37</b>: <b>Notifications page with profiles (like PRTG)</b>. A profile says <i>how</i> and <i>to whom</i>: e-mail addresses, SMS numbers (new <b>SMPP</b> gateway support) and a webhook address (generic, Slack or <b>Microsoft Teams card</b> format). Rules now simply tick one or more profiles; the text, severity and pause between alerts stay in the rule. The E-mail server and SMS gateway settings, a <b>Test</b> button per profile and a <b>delivery log</b> are on the new <b>Notifications</b> page. Old per-rule e-mail and webhook settings are converted to profiles automatically.</li>
    <li><b>1.36</b>: <b>Any visual on any data</b>. <b>Add tile</b> now shows every visual as a picture (like Power BI), then asks for the <b>data</b>: Syslog messages, SNMP traps, both, Alarms, Devices or System. Each tile shows its data name in the header. Alarm cards are ordinary Number tiles on the Alarms data, so charts, tables, gauges and lists work for alarms and devices too. New <b>Calculations</b> (percent of another number, ratio, difference, per minute / hour / day, change since the period before, multiply and add; running total, moving average and per-minute rate for charts), a <b>device filter</b> for the whole dashboard, and <b>named dashboards</b> (Save as, New, Rename, Delete).</li>
    <li><b>1.35.1</b>: <b>Recovery e-mail</b>: an escalated alarm now sends a green CLEARED e-mail to the same recipients when it clears (per-rule switch “e-mail when it clears”).</li>
    <li><b>1.35</b>: <b>Tile editor with live preview</b> and the same panel options for every tile (background, gradient, border, shadow, title bar, value size and units, colour steps, gauge styles, chart options, palettes). Alarm cards are ordinary tiles. <b>Quick look</b> restyles the whole board. SNMP first / Syslog first is now a switch; the Style and Full screen buttons are gone.</li>
    <li><b>1.34</b>: <b>Dashboard studio</b>: Power BI and Grafana style visuals (bar chart, treemap, table, bar gauge, number with trend line, text note), eleven colour themes, card styles, a Style dialog (radius, spacing, row height, accent, refresh interval), amber/red levels on numbers and a full screen wall mode.</li>
    <li><b>1.33</b>: <b>Network share sign-in</b>: user name and password fields for the report folder and the backup copy folder, so a share can be used without changing the service account.</li>
    <li><b>1.32.1</b>: A report or backup folder on a network share (<code>\\\\server\\share</code>) no longer fails with “EPERM: operation not permitted, mkdir”; the error texts explain share permissions.</li>
    <li><b>1.32</b>: <b>Text replacement for SNMP traps works on the trap columns</b>, for old and new traps, with a choice of the columns (Settings → Text replacement → Trap columns). Exports and e-mail reports show the same text.</li>
    <li><b>1.31.5</b>: In a trap column lookup several values can share one entry: <code>0,2,3,8=Critical</code>.</li>
    <li><b>1.31</b>: <b>Lean probe.</b> A probe now runs as a small program of its own: listeners, a queue on disk and a status page for the probe PC only. The setup program has a <b>Probe only</b> choice (also silent: <code>/PROBE=1 /SERVER= /TOKEN= /NAME=</code>), and probes can be updated from their own page. See <a href="#probes">Remote probes</a>.</li>
    <li><b>1.30.2</b>: The program folder <code>C:\\Program Files\\SyslogPro</code> is also renamed to <code>NetEventPro</code> by the new setup program (the old folder is removed after the files are installed).</li>
    <li><b>1.30.1</b>: Everything is now called NetEventPro inside as well: service id, firewall rule, data folder <code>C:\\ProgramData\\NetEventPro</code>, tray program, certificate and backup file names, environment variables <code>NETEVENTPRO_*</code>. Run the new setup program once over an existing installation to convert it (settings, messages and backups are kept).</li>
    <li><b>1.30</b>: <b>Same columns everywhere.</b> CSV, Excel and PDF exports and scheduled reports now use the columns, order and names you chose on the Logs, Traps and Alarms windows (including trap column views). <b>Devices</b>: the duplicate IP-address rows are merged into the named device, and the vendor is filled in for SNMP trap devices from the enterprise number (Dell, Eltek, APC, Cisco …). <b>Text replacement</b> now has a scope for <i>SNMP trap name and values</i> and an optional “Only in trap value” column; plain numbers never change OIDs. <b>E-mail reports</b> have a new aligned layout that also reads well on a phone. New installs use the folder <code>NetEventPro</code>.</li>
    <li><b>1.29</b>: New <i>MIB assistant</i> in Settings → SNMP &amp; MIBs. It lists traps that no MIB names, says why (no MIB for the vendor, different OID, trap not defined, missing import) and what to download.</li>
    <li><b>1.28</b>: About 200 standard MIBs are installed with the program (<code>starter-mibs</code> folder) and names are resolved per MIB module, so two vendors using the same name no longer clash.</li>
    <li><b>1.27</b>: NOC panels theme; Eltek SP2 trap rule.</li>
    <li><b>Earlier</b>: Settings tabs, compact Devices page, system-message switch, rule and trap-view export/import, SNMPv3, remote probes, roles and groups, reports in PDF/Excel/CSV, signed online updates. The full list is in <code>CHANGELOG.md</code> in the program folder.</li></ul>
  ` },
  { id: 'reports', title: 'Reports', html: `
    <p>Scheduled reports summarise a period and are delivered as <b>PDF, Excel (.xlsx) and/or CSV</b> by e-mail, to a folder (local or network share), or both. Times are the server's local time.</p>
    <ol><li><b>Add report</b> (or start from an example). Choose when it runs (hourly, daily, weekly, monthly) and the period it covers (last 24 hours, yesterday, previous 7 days, previous month …).</li>
    <li><b>Include</b>: filter by severities, device, process, tag or text. <b>Contents</b>: the summary page (totals, severity chart, trend, busiest devices and processes) is always included; tick “List the messages” to add them.</li>
    <li><b>Network share as the report folder</b>: below the folder box type the <b>share sign-in</b> (user and password, for example <code>CORP\\svc-reports</code> or <code>.\\reportuser</code> for a local user of the file server) and press <b>Test folder</b>. NetEventPro then signs in to the share with that user before it saves, so the service account does not matter. The user needs <b>Change</b> permission on the share and on the folder. The password is stored in the settings file (not shown again on screen). Without a sign-in the service uses the computer account <code>DOMAIN\\COMPUTERNAME$</code>. The backup page has the same sign-in for “Also copy to a folder”. If the test says the network path was not found, check the server address, the share name (<code>Get-SmbShare</code> on the server) and that TCP port 445 is open (<code>Test-NetConnection 10.1.1.5 -Port 445</code>).</li>
    <li><b>Send</b>: e-mail needs Notifications → E-mail server to be set up (recipients empty = the default alert list; attachments up to 20 MB). For a folder enter a full path such as <code>D:\\Reports</code> or <code>\\\\server\\share\\reports</code> and use <b>Test folder</b>. “Keep newest” removes older files of this report only.</li>
    <li><b>Save reports</b>, then <b>Run now</b> to test, or download a PDF / Excel / CSV directly.</li></ol>
    <p>The service account must be allowed to write to the folder. Network shares often need a domain account for the service (Windows services → NetEventPro → Log On).</p>` },
  { id: 'users', title: 'Users, roles & groups', html: `
    <p>Users, roles and groups are managed in <b>Settings → Users</b>. Turn sign-in on first: <b>Settings → Dashboard access → Password</b> (this is the built-in <code>admin</code> account, which always has every permission). Everyone then signs in on NetEventPro's own sign-in page (the <b>Sign out</b> link is under the menu, bottom left); a session lasts 12 hours of inactivity and ends when the service restarts or a password changes. Then add people on the <b>Users</b> page.</p>
    <ul><li>A <b>role</b> is a set of permissions: view, customize dashboards, export, edit rules, change settings, manage reports, backup &amp; restore, manage users, acknowledge alarms, delete, and <b>SNMP polling</b> (Administrator only by default). Three roles are ready-made (Administrator, Operator, Viewer); create your own.</li>
    <li>A <b>group</b> carries roles too. A person's permissions are those of their role plus all roles of their groups.</li>
    <li><b>Password reset</b>: an administrator types a new password in the user's row and saves (the user is asked to sign in again). Everyone can change their own password under “My password”; the built-in administrator can be reset only by itself.</li>
    <li>Untick/tick <b>Off</b> to disable a person without deleting them. Pages a person may not use are hidden, and the server refuses the action anyway.</li></ul>
    <p>“Manage users, roles and groups” is as powerful as administrator — give it only to administrators.</p>` },
  { id: 'backup', title: 'Backup & restore', html: `
    <p>Found in <b>Settings → Backup</b>. A backup is one <code>.spbak</code> file with the message database, settings, rules, reports and users. It can be encrypted with a passphrase (needed again to restore — keep it safe).</p>
    <ul><li><b>Create backup now</b> saves it under <code>backups</code> in the data folder; <b>Download</b> it to keep a copy elsewhere. A database backup is consistent even while messages arrive.</li>
    <li><b>Automatic daily backup</b>: pick a time, how many to keep, optionally also copy to a network folder.</li>
    <li><b>Restore</b>: choose a saved backup (or upload one), enter the passphrase if needed, tick what to restore (messages, settings, users) and confirm. The restore is checked first and applied when the service restarts; your current files are kept in a <code>before-restore-…</code> folder. Settings include ports and the dashboard password, so after restoring settings from another computer you may need to adjust them.</li></ul>` },
  { id: 'settings', title: 'Settings', html: `
    <p>Settings is split into <b>tabs</b> (Syslog, SNMP, Trap columns, Text replacement, Storage, Access, Appearance, Notifications and, with the right permission, <b>Users</b>, <b>Backup</b> and <b>Maintenance</b>). The tab bar stays in view while you scroll. <b>System messages</b> (in the Syslog tab) chooses which of NetEventPro's own messages are written to the log: all, health only, silent devices only, audit only, or none.</p>
    <ul><li><b>Syslog inputs</b>: UDP/TCP ports, listen address and “Accept syslog only from” (a list of addresses/networks).</li>
    <li><b>Dashboard access</b>: port, who can open it (this computer or the network), the admin password and optional HTTPS certificate.</li>
    <li><b>Storage</b>: keep messages for N days and/or up to N MB (oldest are removed first), optional plain-text daily log files.</li>
    <li><b>Log appearance</b>, <b>Text replacement</b> (show names instead of IP addresses — the original packet stays in the details), <b>Vendor recognition</b> (adds tags such as <code>link-down</code>, <code>on-battery</code>, <code>mains-failure</code> for Cisco, Dell, HP, APC and Eltek messages — best-effort, so check them against your devices), <b>Sound and desktop alerts</b>.</li>
    <li><b>Forward to another collector</b> (e-mail, SMS and webhooks are on the <b>Notifications</b> page), <b>Where your data is stored</b> and <b>Tools</b> (send a test message, download a database copy, restart).</li></ul>` },
  { id: 'snmpver', title: 'SNMP version column', html: `
    <p>Every trap is received as SNMP v1, v2c or v3. The version is shown in its own column, <b>SNMP</b>, which is available but hidden by default.</p>
    <ol><li>Open the <b>Traps</b> page (Logs with source SNMP).</li>
    <li>Click <b>Columns</b> above the table.</li>
    <li>Tick <b>SNMP version</b>, drag it to the place you want and press OK. The choice is saved on the server for all your browsers.</li></ol>
    <ul><li>The column is also used by the CSV / Excel / PDF exports and reports of the Traps page.</li>
    <li>In a trap column view (Settings → Trap columns) use the value <code>{version}</code> to show it as part of your own column.</li>
    <li>To filter by version search for the text <code>SNMPv2c</code>, <code>SNMPv1</code> or <code>SNMPv3</code>.</li></ul>` },
  { id: 'https', title: 'HTTPS certificate: create and use', html: `
    <p>Use HTTPS whenever anybody opens the dashboard from another computer, otherwise the password and log data cross the network readable. There are two ways.</p>
    <h4>A. Self-signed certificate made by NetEventPro (simplest)</h4>
    <ol><li>Settings → <b>Dashboard access</b> → <b>Create a certificate here…</b></li>
    <li>List every name and IP address people will type in the browser, for example <code>nms.corp.local, 10.1.1.20</code>, and the number of years.</li>
    <li>Create. The certificate and key files are written in the data folder and filled into the two HTTPS boxes. <b>Save</b>, then restart the service (Services → the NetEventPro service → Restart, or run PowerShell as administrator: <code>Restart-Service NetEventPro</code> (an installation made before 1.30.1 and not yet re-installed with the new setup program still has the service id <code>SyslogPro</code>)).</li>
    <li>Open <code>https://nms.corp.local:8514/</code>. The browser shows “not secure” until the certificate is trusted: click <b>Download certificate</b> and install it on each PC: double-click the file → Install Certificate → Local Machine → Place all certificates in the following store → <b>Trusted Root Certification Authorities</b>. Restart the browser.</li></ol>
    <h4>B. Certificate with OpenSSL (or from your company CA)</h4>
    <ol><li>Create a key and request (run in a folder such as <code>C:\\certs</code>):<br><code>openssl req -new -newkey rsa:2048 -nodes -keyout neteventpro.key -out neteventpro.csr -subj "/CN=nms.corp.local"</code></li>
    <li>Give the .csr to your certificate authority and receive a .crt (PEM, Base64). For a quick self-signed file use instead:<br><code>openssl req -x509 -newkey rsa:2048 -nodes -days 825 -keyout neteventpro.key -out neteventpro.crt -subj "/CN=nms.corp.local" -addext "subjectAltName=DNS:nms.corp.local,IP:10.1.1.20"</code></li>
    <li>If the CA gave a .pfx: <code>openssl pkcs12 -in file.pfx -nocerts -nodes -out neteventpro.key</code> and <code>openssl pkcs12 -in file.pfx -clcerts -nokeys -out neteventpro.crt</code></li>
    <li>Settings → Dashboard access: type the two file paths (<code>C:\\certs\\neteventpro.crt</code>, <code>C:\\certs\\neteventpro.key</code>), Save and restart the service. The service account must be able to read the files.</li></ol>
    <ul><li>The name in the browser address must be in the certificate (name or IP), or the browser warns.</li>
    <li>Remote probes use the same address: use <code>https://…</code> there and tick “allow self-signed” on the probe if you did not install the certificate.</li>
    <li>Renew before it expires: create again with the same names and restart. Check the date with <code>openssl x509 -in neteventpro.crt -noout -enddate</code>.</li>
    <li>If the dashboard will not open after a change, edit <code>config.json</code> in the data folder, set <code>"tlsCertFile": ""</code> and <code>"tlsKeyFile": ""</code>, then restart the service.</li></ul>` },
  { id: 'smtpfw', title: 'E-mail ports and port forwarding', html: `
    <p>NetEventPro sends alerts and reports to a mail server over SMTP. Settings → <b>Email</b> has server, port and encryption: <b>587</b> STARTTLS, <b>465</b> SSL/TLS, <b>25</b> no encryption. Press the test button after saving; the error text comes from the mail server.</p>
    <h4>1. Check that the port is reachable (PowerShell on the NetEventPro PC)</h4>
    <p><code>Test-NetConnection smtp.example.com -Port 587</code> — <code>TcpTestSucceeded : True</code> means the path is open. If False, the firewall or the network blocks outgoing traffic on that port.</p>
    <h4>2. Allow the port out through Windows Firewall (administrator PowerShell)</h4>
    <p><code>New-NetFirewallRule -DisplayName "NetEventPro SMTP out" -Direction Outbound -Protocol TCP -RemotePort 587 -Action Allow</code></p>
    <h4>3. Forward a local port to the mail server (when the mail server must be reached through this PC or the PC can only reach an internal relay)</h4>
    <p>Windows can pass TCP connections on with a port proxy. Run as administrator:</p>
    <p><code>netsh interface portproxy add v4tov4 listenaddress=0.0.0.0 listenport=2525 connectaddress=10.1.1.25 connectport=25</code><br>
    <code>New-NetFirewallRule -DisplayName "SMTP relay 2525" -Direction Inbound -Protocol TCP -LocalPort 2525 -Action Allow</code><br>
    <code>netsh interface portproxy show all</code><br>
    <code>netsh interface portproxy delete v4tov4 listenaddress=0.0.0.0 listenport=2525</code> (remove it)</p>
    <p>The service “IP Helper” must be running for the port proxy. Port proxy handles TCP only, not UDP, so it does not apply to syslog (UDP 514) or traps (UDP 162).</p>
    <h4>4. Router / firewall (devices in other networks sending to NetEventPro)</h4>
    <ul><li>On the router or firewall create a rule that forwards <b>UDP 514</b> (syslog), <b>TCP 514</b> (if used) and <b>UDP 162</b> (traps) from the outside address to the NetEventPro PC's fixed IP. For the dashboard forward only the HTTPS port (for example TCP 8514) and use HTTPS with a password.</li>
    <li>Allow the same ports in Windows Firewall (the installer already adds rules for the ports you chose): <code>New-NetFirewallRule -DisplayName "NetEventPro traps" -Direction Inbound -Protocol UDP -LocalPort 162 -Action Allow</code></li>
    <li>Use “Accept syslog only from” in Settings to limit who may send. When a site cannot reach the server directly, a <a href="#probes">remote probe</a> needs only the dashboard port.</li>
    <li>Check what listens: <code>netstat -ano | findstr ":514 :162 :8514"</code></li></ul>
    <h4>Common mail problems</h4>
    <ul><li>Gmail / Microsoft 365 need an app password or an SMTP-allowed account, port 587 with STARTTLS.</li>
    <li>“Certificate” errors with an internal server: tick the self-signed option in Notifications → E-mail server, or use a name that is in the server's certificate.</li>
    <li>Internal relay without login: use port 25, leave user empty, and allow this PC's IP on the relay.</li></ul>` },
  { id: 'updates', title: 'Updates: create and host a release', html: `
    <p>NetEventPro updates itself from a signed release file that you host. Only packages signed with your private key are accepted. Settings → <b>Updates</b> is the page that checks and installs.</p>
    <h4>One time on the build PC</h4>
    <ol><li>Open the program source folder in PowerShell. Create the signing key: <code>node scripts/release.js keygen</code></li>
    <li>This writes <code>release-private.pem</code>. <b>Keep it secret and backed up</b>; never put it on a server. The printed <b>public key</b> is pasted into Settings → Updates → Public key on every NetEventPro server (once).</li></ol>
    <h4>For every new version</h4>
    <ol><li>Raise the version: <code>npm run bump -- patch</code> (fixes) or <code>npm run bump -- minor</code> (new features). Add the notes to <code>CHANGELOG.md</code>; the first entry is shown as the release notes.</li>
    <li>Run the checks: <code>npm test</code></li>
    <li>Build the package: <code>node scripts/release.js build https://your.host/folder/</code> (the address where the two files will be downloadable). It creates <code>release/NetEventPro-&lt;version&gt;.zip</code> and <code>release/latest.json</code> (version, address, SHA-256, signature, notes).</li>
    <li>Upload both files to the host (see below).</li></ol>
    <h4>Hosting choices</h4>
    <ul><li><b>GitHub release</b>: create a release in your repository with the tag <code>v&lt;version&gt;</code> and attach the zip and latest.json. Build with base address <code>https://github.com/&lt;owner&gt;/&lt;repo&gt;/releases/download/v&lt;version&gt;/</code>. The release file address on the servers is the repo's latest-release link: <code>https://github.com/&lt;owner&gt;/&lt;repo&gt;/releases/latest/download/latest.json</code>. A public repository is needed unless the servers can sign in.</li>
    <li><b>Any web server</b> (IIS, nginx, Apache): copy both files to a folder, e.g. <code>C:\\inetpub\\wwwroot\\neteventpro\\</code>, and make sure the .json and .zip types are served. Address: <code>https://updates.corp.local/neteventpro/latest.json</code>.</li>
    <li><b>Internal share over HTTP(S)</b>: publish the folder with IIS; plain file shares (\\\\server\\share) are not supported, the address must start with http:// or https://.</li></ul>
    <h4>On each server</h4>
    <ol><li>Settings → Updates: type the release file address, paste the public key, tick “check automatically” if wanted, <b>Save</b>.</li>
    <li><b>Check for updates now</b> → <b>Install update</b>. The service restarts by itself.</li></ol>
    <ul><li>Only program files (<code>src</code>, <code>public</code>, <code>scripts</code>, <code>assets</code>, <code>starter-mibs</code>, text files) are replaced. Settings, database, users and the Node runtime are untouched.</li>
    <li>The old files are kept in the data folder under <code>updates\\backup-&lt;version&gt;</code>. If the new version does not start 3 times it is restored automatically.</li>
    <li>Changes to the installer itself (new folder name, service wrapper, Node version) need a full installation with the new setup program; online updates cannot do that.</li>
    <li>If the check says the signature is wrong, the public key on the server does not belong to the key that built the release.</li></ul>` },
  { id: 'tips', title: 'Troubleshooting', html: `
    <table class="data"><tbody>
    <tr><td><b>No messages arrive</b></td><td>Check Health (are the listeners running?), the Windows firewall, that the device points at this PC's IP on port 514, and that its address is allowed under “Accept syslog only from”. Send a test message from Settings → Tools.</td></tr>
    <tr><td><b>Port 514 in use</b></td><td>Another program uses it. The banner at the top names the failed listener. Stop the other program or use another port on both sides.</td></tr>
    <tr><td><b>Browser says “not secure”</b></td><td>Use HTTPS with a certificate that includes the address you type, and trust it on each PC; open the dashboard by that exact name or IP.</td></tr>
    <tr><td><b>A rule did not fire</b></td><td>Rules run top to bottom; an earlier rule that <i>discards</i> stops later ones. Check the conditions on a real message (details panel → “Create rule from message”).</td></tr>
    <tr><td><b>E-mail fails</b></td><td>Use Notifications → E-mail server → test. The error text comes from your mail server (login, port, STARTTLS/SSL, certificate).</td></tr>
    <tr><td><b>Disk filling</b></td><td>Lower the retention days or maximum size in Settings → Storage, and check Health.</td></tr>
    <tr><td><b>Forgot the admin password</b></td><td>Another administrator can reset only other users. For the built-in admin, stop the service, edit <code>config.json</code> in the data folder and set <code>"adminPasswordHash": ""</code>, start the service, then set a new password in Settings.</td></tr></tbody></table>
    <p>UDP syslog has no delivery guarantee; very bursty senders should use TCP.</p>` }
];

views.help = (el) => {
  el.innerHTML = `<div class="page-head"><h1>User guide</h1><span class="muted" id="hInfo"></span></div>
    <div class="guide"><nav class="guide-toc" aria-label="Guide contents"><input type="search" id="gSearch" placeholder="Search the guide" aria-label="Search the guide">
      ${GUIDE.map((g) => `<a href="#help" data-g="${g.id}">${esc(g.title)}</a>`).join('')}</nav>
      <div class="guide-body" id="gBody">${GUIDE.map((g) => `<section class="panel guide-sec" id="g-${g.id}" data-g="${g.id}"><h2>${esc(g.title)}</h2>${g.html}</section>`).join('')}<div class="empty" id="gNone" hidden><b>Nothing found</b>Try another word.</div></div></div>`;
  const body = $('#gBody', el);
  const search = () => {
    const q = $('#gSearch', el).value.trim().toLowerCase(); let n = 0;
    for (const s of $$('.guide-sec', el)) { const hit = !q || s.textContent.toLowerCase().includes(q); s.hidden = !hit; if (hit) n++; }
    $('#gNone', el).hidden = n > 0; $('#hInfo', el).textContent = q ? `${n} section${n === 1 ? '' : 's'} match` : '';
  };
  $('#gSearch', el).oninput = search;
  el.querySelector('.guide-toc').addEventListener('click', (e) => { const a = e.target.closest('a[data-g]'); if (!a) return; e.preventDefault(); $('#gSearch', el).value = ''; search(); $('#g-' + a.dataset.g, el)?.scrollIntoView({ block: 'start', behavior: 'smooth' }); });
  body.addEventListener('click', (e) => { const a = e.target.closest('a[href^="#"]'); if (a && a.getAttribute('href') !== '#help') { e.preventDefault(); location.hash = a.getAttribute('href'); } });
};
